async function loadDashboard(userId, { signal }) {
  const [uRes, oRes] = await Promise.all([
    fetch(`/users/${userId}`, { signal }),
    fetch(`/orders?user=${userId}`, { signal }),
  ]);
  if (!uRes.ok) throw new Error(uRes.status);
  const data = await uRes.json();
  document.getElementById("name").textContent = data.name;
  const id = setInterval(() => refresh(userId), 5000);
  return () => clearInterval(id);
}

function parseCached(raw) {
  if (typeof raw !== "string") return null;
  try {
    const data = JSON.parse(raw);
    if (typeof data?.userId !== "string") return null;
    return data;
  } catch { return null; }
}

function safeMerge(target, source) {
  for (const key of Object.keys(source)) {
    if (key === "__proto__" || key === "constructor" || key === "prototype") continue;
    target[key] = source[key];
  }
  return target;
}
